    std::string address(20 * 1024, 'x');
    harness.backend.connection_info.message = address;
    harness.agent->call = Agent::ToolRequest{"printer_connection_status", "{}"};
    harness.say("is it online?");
    harness.pump();
    REQUIRE(harness.agent->results.size() == 1);
